"""
TELECOM CUSTOMER CHURN DASHBOARD
Premium Streamlit + Plotly Dashboard
Single-file implementation

Run:
    streamlit run Churn-Dash.py

Dataset:
    Customer_Churn_Predictions.csv  (must be in the SAME folder)

------------------------------------------------------------------
FIXES APPLIED IN THIS VERSION
------------------------------------------------------------------
1. Reset button crash fixed:
   `st.session_state["filter_quarter"] = "All"` used to be set AFTER
   the selectbox with that same key had already been instantiated in
   the same run, which Streamlit forbids
   (StreamlitAPIException: cannot be modified after the widget ...).
   The reset logic now lives in an on_click callback, which runs
   BEFORE the next script rerun draws the widgets, so mutating
   session_state there is safe and Streamlit-approved.

2. Chart / card alignment fixed:
   Added `align-items: stretch` + flex column CSS on Streamlit's
   horizontal block containers, and standardized min-height on every
   panel-card / vertical-label within each row (424px for Row 1 and
   Row 2's tall columns, 390px for the banner + chart columns) so
   card bottoms line up across a row instead of drifting based on
   how much content each chart happens to have.
------------------------------------------------------------------
"""

