def normalize_column(column_name: str) -> str:
    """
    Normalize a column name for matching.
    """

    return (
        str(column_name)
        .strip()
        .lower()
        .replace(" ", "_")
        .replace("-", "_")
    )


def find_column(dataframe: pd.DataFrame, aliases: list):
    """
    Find an actual dataframe column using aliases.
    """

    normalized = {
        normalize_column(column): column
        for column in dataframe.columns
    }

    for alias in aliases:
        key = normalize_column(alias)
        if key in normalized:
            return normalized[key]

    return None


