def create_churn_flag(dataframe: pd.DataFrame, churn_column):
    """
    Convert the actual churn column into a stable 0/1 series.
    """

    if churn_column is None:
        return pd.Series(np.nan, index=dataframe.index, dtype=float)

    series = dataframe[churn_column]

    # ---------------------------------------------------------------
    # Numeric target
    # ---------------------------------------------------------------

    numeric = pd.to_numeric(series, errors="coerce")
    numeric_values = set(numeric.dropna().unique())

    if numeric_values:
        if numeric_values.issubset({0, 1}):
            return numeric.astype(float)

    # ---------------------------------------------------------------
    # Text target
    # ---------------------------------------------------------------

    text = series.astype(str).str.strip().str.lower()

    result = pd.Series(np.nan, index=dataframe.index, dtype=float)

    positive = {
        "yes", "y", "true", "1", "churn",
        "churned", "exited", "left",
    }

    negative = {
        "no", "n", "false", "0",
        "active", "stayed", "retained",
    }

    result[text.isin(positive)] = 1
    result[text.isin(negative)] = 0

    # ---------------------------------------------------------------
    # Customer Status fallback
    # ---------------------------------------------------------------

    if result.notna().sum() == 0:
        result[text.str.contains("churn", na=False)] = 1
        result[
            text.str.contains(
                "active|joined|stayed|retained",
                regex=True,
                na=False,
            )
        ] = 0

    return result


df["_dashboard_churn_flag"] = create_churn_flag(df, CHURN_COL)

