def style_fig(fig: go.Figure, height: int = 300, show_legend: bool = False):
    """
    Apply the common dashboard Plotly style.
    """

    fig.update_layout(
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color=TEXT, family="Arial, sans-serif", size=11),
        margin=dict(l=8, r=8, t=8, b=8),
        height=height,
        showlegend=show_legend,
        hovermode="closest",
        uirevision="telecom-churn-dashboard",
        transition={"duration": 0},
        legend=dict(
            orientation="h",
            yanchor="bottom",
            y=1.0,
            x=0,
            font=dict(size=10, color=TEXT),
        ),
    )

    fig.update_xaxes(
        gridcolor=GRID,
        zerolinecolor=GRID,
        linecolor=GRID,
        tickfont=dict(color=SUBTEXT, size=10),
        title_font=dict(color=SUBTEXT, size=10),
    )

    fig.update_yaxes(
        gridcolor=GRID,
        zerolinecolor=GRID,
        linecolor=GRID,
        tickfont=dict(color=SUBTEXT, size=10),
        title_font=dict(color=SUBTEXT, size=10),
    )

    return fig


# =====================================================================
# HTML HELPERS
# =====================================================================

def flatten_html(html: str) -> str:
    """
    Strip per-line leading/trailing whitespace from a raw HTML string
    before it goes to st.markdown(..., unsafe_allow_html=True).

    Root cause this fixes: every HTML snippet in this file used to be
    written as a Python multi-line f-string, which inherits the
    indentation of the surrounding Python code (4, 8, even 20+ spaces
    deep once nested inside "with st.container(): / if: / for:"
    blocks). Once that indentation reaches a handful of spaces,
    Streamlit's markdown renderer can stop treating the block as raw
    HTML and instead render it as a literal, unparsed code block -
    exactly what made the "Churn by Services" table show up as plain
    <div> tag text on the page instead of a styled table, and made
    KPI / illustration cards render with the wrong shape.

    Stripping every line down to its own content (HTML doesn't care
    about whitespace between block-level tags) removes that risk
    completely, regardless of how deeply nested the Python code that
    built the string happens to be.
    """
    lines = [line.strip() for line in html.strip("\n").split("\n")]
    return "\n".join(lines)


def render_html(html: str) -> None:
    """Render a raw HTML string safely (see flatten_html)."""
    st.markdown(flatten_html(html), unsafe_allow_html=True)


def kpi_card(icon, value, label, color_1, color_2) -> str:
    return flatten_html(f"""
    <div class="kpi-card" style="background: linear-gradient(135deg, {color_1}, {color_2});">
        <div class="kpi-row">
            <div class="kpi-icon">{icon}</div>
            <div>
                <div class="kpi-value">{value}</div>
                <div class="kpi-label">{label}</div>
            </div>
        </div>
    </div>
    """)


def gender_icon_data_uri() -> str:
    """
    Returns the exact reference male/female icon (embedded as base64)
    to be placed at the centre of the donut chart.
    """

    return GENDER_ICON_IMAGE_DATA_URI


def section_banner(text, color) -> str:
    return flatten_html(f"""
    <div class="section-banner" style="background:{color};">
        {text}
    </div>
    """)


def vertical_label(text, css_class="") -> str:
    return flatten_html(f"""
    <div class="vertical-label {css_class}">
        <span>{text}</span>
    </div>
    """)


