with row1_c0:
    st.markdown(vertical_label("DEMOGRAPHIC"), unsafe_allow_html=True)

with row1_c1:
    # FIX #3: use a real st.container(key=...) so the title, chart and
    # caption are ACTUALLY nested inside one styled card (see CSS note
    # above). This replaces the old "open div in one markdown call,
    # close it in a later call" pattern that never really wrapped the
    # chart and caused the "blank card on top, plain chart below" bug.
    with st.container(key="panelcard_gender"):
        st.markdown(
            """<div class="panel-title">Total Churn by Gender</div>""",
            unsafe_allow_html=True,
        )

        if GENDER_COL is not None and total_churn is not None:
            churned_df = df[df["_dashboard_churn_flag"] == 1].copy()
            gender_counts = churned_df[GENDER_COL].dropna().astype(str).value_counts()

            preferred_order = ["Female", "Male"]
            ordered_gender = [g for g in preferred_order if g in gender_counts.index]
            remaining_gender = sorted(
                [g for g in gender_counts.index if g not in ordered_gender]
            )
            ordered_gender.extend(remaining_gender)
            gender_counts = gender_counts.reindex(ordered_gender).dropna()

            color_map = {"Female": PURPLE, "Male": BLUE}
            gender_colors = [color_map.get(g, TEAL) for g in gender_counts.index]

            fig = go.Figure(
                go.Pie(
                    labels=gender_counts.index,
                    values=gender_counts.values,
                    hole=0.62,
                    marker=dict(colors=gender_colors, line=dict(color=CARD, width=3)),
                    textinfo="none",
                    hovertemplate="<b>%{label}</b><br>Churned Customers: %{value:,}<br>Share: %{percent}<extra></extra>",
                )
            )

            fig.update_layout(
                legend=dict(
                    orientation="h", y=-0.05, x=0.5, xanchor="center",
                    font=dict(color=TEXT, size=10),
                ),
            )

            fig.add_layout_image(
                dict(
                    source=gender_icon_data_uri(),
                    xref="paper",
                    yref="paper",
                    x=0.5,
                    y=0.52,
                    sizex=0.34,
                    sizey=0.34,
                    xanchor="center",
                    yanchor="middle",
                    layer="above",
                )
            )

            fig = style_fig(fig, height=245, show_legend=True)

            st.plotly_chart(
                fig, use_container_width=True,
                config={"displayModeBar": False, "responsive": True},
                key="gender_donut_chart",
            )

            total_gender = gender_counts.sum()
            gender_text = "   ".join(
                f"{g}: {c:,} ({c / total_gender * 100:.1f}%)"
                for g, c in gender_counts.items()
            )
            st.caption(gender_text)
        else:
            st.info("Gender churn data is not available.")

