with row2_c4:
    st.markdown(section_banner("CHURN BY SERVICES", AMBER), unsafe_allow_html=True)
    # FIX #3: 390px, real container - the service table now actually
    # renders inside the styled card instead of below an empty box.
    with st.container(key="panelcard_services"):
        available_services = [c for c in SERVICE_COLUMNS if c in df.columns]

        if available_services:
            service_rows_html = ""
            for service in available_services:
                values = df[service].astype(str).str.strip().str.lower()
                yes_rate = values.eq("yes").mean() * 100
                no_rate = values.eq("no").mean() * 100
                service_name = service.replace("_", " ")

                # FIX #5: build each row as flattened (no leading-space)
                # HTML - the accumulated, deeply-indented multi-line
                # f-string here was the exact cause of the "Churn by
                # Services" table showing up as raw <div> tag text
                # instead of a rendered table.
                service_rows_html += flatten_html(f"""
                <div class="service-row">
                    <div class="service-name">{service_name}</div>
                    <div class="service-no" title="No: {no_rate:.1f}%">{no_rate:.1f}%</div>
                    <div class="service-yes" title="Yes: {yes_rate:.1f}%">{yes_rate:.1f}%</div>
                </div>
                """) + "\n"

            render_html(f"""
            <div class="service-table">
                <div class="service-header">
                    <div>Services</div>
                    <div>No</div>
                    <div>Yes</div>
                </div>
                {service_rows_html}
            </div>
            """)
        else:
            st.info("No compatible service columns were found in the dataset.")


